     1→import type { IconData } from "@/components/ui/icon-picker";
     2→
     3→export type ExtractedNavItemKind = "page-mention" | "external-link" | "embed";
     4→
     5→export interface ExtractedNavigationItem {
     6→  id: string;
     7→  kind: ExtractedNavItemKind;
     8→  label?: string;
     9→  blockId?: string;
    10→  order: number;
    11→  pageSlug?: string;
    12→  url?: string;
    13→  nav?: YooptaNavigationMeta;
    14→}
    15→
    16→export interface PageNavigationExtract {
    17→  pageSlug: string;
    18→  items: ExtractedNavigationItem[];
    19→}
    20→
    21→export interface YooptaNavigationMeta {
    22→  includeInPageIndex?: boolean;
    23→  titleOverride?: string;
    24→  iconOverride?: IconData;
    25→  webViewMode?: "embedded" | "external";
    26→}
    27→
    28→const MARKDOWN_LINK_RE = /\[([^\]]+)\]\(([^)\s]+)(?:\s+"([^"]+)")?\)/g;
    29→const MARKDOWN_AUTOLINK_RE = /(?<!\]\()https?:\/\/[^\s)]+/g;
    30→const HTML_COMMENT_NAV_RE = /<!--\s*viben:nav\s+({[\s\S]*?})\s*-->/gi;
    31→const RAW_URL_RE = /^https?:\/\//i;
    32→
    33→type MaybeRecord = Record<string, unknown>;
    34→
    35→function isRecord(value: unknown): value is MaybeRecord {
    36→  return typeof value === "object" && value !== null;
    37→}
    38→
    39→function parseMeta(raw: string | undefined): YooptaNavigationMeta | undefined {
    40→  if (!raw) return undefined;
    41→  try {
    42→    const parsed = JSON.parse(raw);
    43→    if (!isRecord(parsed)) return undefined;
    44→    const meta: YooptaNavigationMeta = {};
    45→    if (typeof parsed.includeInPageIndex === "boolean") {
    46→      meta.includeInPageIndex = parsed.includeInPageIndex;
    47→    }
    48→    if (typeof parsed.titleOverride === "string" && parsed.titleOverride.trim()) {
    49→      meta.titleOverride = parsed.titleOverride.trim();
    50→    }
    51→    if (isRecord(parsed.iconOverride) && typeof parsed.iconOverride.type === "string" && typeof parsed.iconOverride.value === "string") {
    52→      meta.iconOverride = {
    53→        type: parsed.iconOverride.type as "lucide" | "emoji" | "image",
    54→        value: parsed.iconOverride.value,
    55→      };
    56→    }
    57→    if (parsed.webViewMode === "embedded" || parsed.webViewMode === "external") {
    58→      meta.webViewMode = parsed.webViewMode;
    59→    }
    60→    return Object.keys(meta).length > 0 ? meta : undefined;
    61→  } catch {
    62→    return undefined;
    63→  }
    64→}
    65→
    66→function decodePageSlug(raw: string): string {
    67→  return raw
    68→    .replace(/^pages\//, "")
    69→    .replace(/\/SKILL\.md$/i, "")
    70→    .replace(/^\//, "")
    71→    .trim();
    72→}
    73→
    74→function getExternalLabel(label: string | undefined, url: string): string {
    75→  const cleaned = label?.trim();
    76→  if (cleaned) return cleaned;
    77→  try {
    78→    return new URL(url).hostname;
    79→  } catch {
    80→    return url;
    81→  }
    82→}
    83→
    84→function pushUnique(items: ExtractedNavigationItem[], item: ExtractedNavigationItem) {
    85→  const exists = items.some((candidate) => {
    86→    if (candidate.kind !== item.kind) return false;
    87→    if (candidate.pageSlug && item.pageSlug) return candidate.pageSlug === item.pageSlug;
    88→    if (candidate.url && item.url) return candidate.url === item.url;
    89→    return candidate.id === item.id;
    90→  });
    91→  if (!exists) items.push(item);
    92→}
    93→
    94→function buildMentionItem(
    95→  pageSlug: string,
    96→  order: number,
    97→  label?: string,
    98→  nav?: YooptaNavigationMeta,
    99→): ExtractedNavigationItem | null {
   100→  const normalized = decodePageSlug(pageSlug);
   101→  if (!normalized) return null;
   102→  return {
   103→    id: `page:${normalized}:${order}`,
   104→    kind: "page-mention",
   105→    label: label?.trim() || normalized.split("/").filter(Boolean).slice(-1)[0] || normalized,
   106→    order,
   107→    pageSlug: normalized,
   108→    nav,
   109→  };
   110→}
   111→
   112→function buildExternalItem(
   113→  url: string,
   114→  order: number,
   115→  kind: "external-link" | "embed",
   116→  label?: string,
   117→  blockId?: string,
   118→  nav?: YooptaNavigationMeta,
   119→): ExtractedNavigationItem | null {
   120→  if (!RAW_URL_RE.test(url)) return null;
   121→  return {
   122→    id: `${kind}:${url}:${order}`,
   123→    kind,
   124→    label: getExternalLabel(label, url),
   125→    order,
   126→    url,
   127→    blockId,
   128→    nav,
   129→  };
   130→}
   131→
   132→export function extractPageNavigation(
   133→  pageSlug: string,
   134→  content: string,
   135→): PageNavigationExtract {
   136→  const items: ExtractedNavigationItem[] = [];
   137→  const body = content ?? "";
   138→  let order = 0;
   139→
   140→  for (const match of body.matchAll(HTML_COMMENT_NAV_RE)) {
   141→    const nav = parseMeta(match[1]);
   142→    if (!nav) continue;
   143→    const offset = match.index ?? 0;
   144→    const nearby = body.slice(offset + match[0].length, offset + match[0].length + 240);
   145→    const linkMatch = MARKDOWN_LINK_RE.exec(nearby);
   146→    MARKDOWN_LINK_RE.lastIndex = 0;
   147→    if (!linkMatch) continue;
   148→    const [, label, target] = linkMatch;
   149→    const item = RAW_URL_RE.test(target)
   150→      ? buildExternalItem(target, order++, "external-link", label, undefined, nav)
   151→      : buildMentionItem(target, order++, label, nav);
   152→    if (item) pushUnique(items, item);
   153→  }
   154→
   155→  for (const match of body.matchAll(MARKDOWN_LINK_RE)) {
   156→    const label = match[1];
   157→    const target = match[2];
   158→    const item = RAW_URL_RE.test(target)
   159→      ? buildExternalItem(target, order++, "external-link", label)
   160→      : buildMentionItem(target, order++, label);
   161→    if (item) pushUnique(items, item);
   162→  }
   163→
   164→  for (const match of body.matchAll(MARKDOWN_AUTOLINK_RE)) {
   165→    const item = buildExternalItem(match[0], order++, "external-link");
   166→    if (item) pushUnique(items, item);
   167→  }
   168→
   169→  return {
   170→    pageSlug,
   171→    items: items.sort((left, right) => left.order - right.order),
   172→  };
   173→}
   174→
   175→export function collectPageNavigationFromDom(root: ParentNode, pageSlug: string): PageNavigationExtract {
   176→  const items: ExtractedNavigationItem[] = [];
   177→  let order = 0;
   178→
   179→  const mentions = Array.from(root.querySelectorAll<HTMLElement>("[data-mention-type='page'][data-mention-id]"));
   180→  for (const node of mentions) {
   181→    const id = node.dataset.mentionId;
   182→    const item = id ? buildMentionItem(id, order++, node.textContent ?? undefined) : null;
   183→    if (item) pushUnique(items, item);
   184→  }
   185→
   186→  const links = Array.from(root.querySelectorAll<HTMLAnchorElement>("a[href]"));
   187→  for (const link of links) {
   188→    const href = link.getAttribute("href");
   189→    if (!href) continue;
   190→    const item = RAW_URL_RE.test(href)
   191→      ? buildExternalItem(href, order++, "external-link", link.textContent ?? undefined)
   192→      : buildMentionItem(href, order++, link.textContent ?? undefined);
   193→    if (item) pushUnique(items, item);
   194→  }
   195→
   196→  const embeds = Array.from(root.querySelectorAll<HTMLIFrameElement>("iframe[src]"));
   197→  for (const embed of embeds) {
   198→    const src = embed.getAttribute("src");
   199→    if (!src) continue;
   200→    const item = buildExternalItem(src, order++, "embed", embed.title || undefined);
   201→    if (item) pushUnique(items, item);
   202→  }
   203→
   204→  return {
   205→    pageSlug,
   206→    items: items.sort((left, right) => left.order - right.order),
   207→  };
   208→}
