   199→// ── Edge Index ──
   200→// Pre-built lookup: given a parent descriptor id, returns valid child descriptor ids.
   201→// Use `getChildDescriptors(parentId)` to query valid transitions.
   202→// Use `resolveItemDescriptor(item, parentDescriptorId)` to find an item's descriptor.
   203→
   204→export interface TabNavigationState {
