   430→export function locationToUrl(location: DesktopLocation): string {
   431→  switch (location.kind) {
   432→    case "workspace-home":
   433→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}`, location);
   434→    case "workspace-apps":
   435→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/apps`, location);
   436→    case "workspace-section":
   437→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/${location.section}`, location);
   438→    case "workspace-agent-detail":
   439→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/agent/${encodeURIComponent(location.agentId)}`, location);
   440→    case "workspace-executor-detail":
   441→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/executor/${encodeURIComponent(location.executorType)}`, location);
   442→    case "workspace-page": {
   443→      const encodedSlug = location.pageSlug.split("/").filter(Boolean).map((segment) => encodeURIComponent(segment)).join("/");
   444→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/page/${encodedSlug}`, location);
   445→    }
   446→    case "workspace-web": {
   447→      const params = new URLSearchParams({ url: location.url, title: location.title });
   448→      if (location.sourcePageSlug) params.set("source_page", location.sourcePageSlug);
   449→      if (location.webId) params.set("web_id", location.webId);
   450→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/web?${params.toString()}`, location);
   451→    }
   452→    case "agent-detail":
   453→      return appendUrlSuffix(`/agent/${encodeURIComponent(location.agentId)}${buildDetailQuery(location.workspacePath)}`, location);
   454→    case "executor-detail":
   455→      return appendUrlSuffix(`/executor/${encodeURIComponent(location.executorType)}${buildDetailQuery(location.workspacePath)}`, location);
   456→    case "skill-detail":
   457→      return appendUrlSuffix(`/skill/${encodeURIComponent(location.skillId)}${buildDetailQuery(location.workspacePath, { agent_id: location.agentId })}`, location);
   458→    case "mcp-server-detail":
   459→      return appendUrlSuffix(`/mcp-server/${encodeURIComponent(location.serverName)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   460→    case "subagent-detail":
   461→      return appendUrlSuffix(`/subagent/${encodeURIComponent(location.configId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   462→    case "prompt-detail":
   463→      return appendUrlSuffix(`/prompt/${encodeURIComponent(location.promptId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   464→    case "command-detail":
   465→      return appendUrlSuffix(`/command/${encodeURIComponent(location.commandId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   466→    case "settings":
   467→      return appendUrlSuffix(location.section ? `/settings/${encodeURIComponent(location.section)}` : "/settings/general", location);
   468→    case "documents":
   469→      return appendUrlSuffix("/documents", location);
   470→    case "device-pair":
   471→      return appendUrlSuffix("/devices/pair", location);
   472→    case "global-route":
   473→      return location.path;
   474→    default: {
   475→      const exhaustive: never = location;
   476→      return exhaustive;
   477→    }
   478→  }
   479→}
