    51→    descriptorId?: string;
    52→    location?: DesktopLocation;
    53→  }
    54→): BreadcrumbStackItem {
    55→  return {
    56→    ...item,
    57→    icon: item.icon ?? getDescriptorIcon(item.descriptorId),
    58→    target: item.location
    59→      ? buildViewTarget(item.location, locationToUrl(item.location))
    60→      : undefined,
    61→  };
    62→}
